/// in the key/value store (e.g. for index lookups).
fn serialize_f64<S: Serializer>(value: &f64, serializer: S) -> StdResult<S::Ok, S::Error> {
    let mut value = *value;
    if (value.is_nan() || value == 0.0) && value.is_sign_negative() {
