impl Plan {
    /// Builds a plan from an AST statement.
    pub fn build(statement: ast::Statement, catalog: &impl Catalog) -> Result<Self> {
        let mut planner = Planner::new(catalog);
        planner.build(statement)
    }

    /// Executes the plan, consuming it.
    pub fn execute(self, txn: &impl Transaction) -> Result<ExecutionResult> {
        let mut executor = Executor::new(txn);
        executor.execute(self)
    }

    /// Optimizes the plan, consuming it.
    pub fn optimize(self) -> Result<Self> {
        let mut plan = self;
        for optimizer in OPTIMIZERS.iter() {
            plan = match plan {
                Plan::Select(node) => {
                    let node = optimizer.optimize(node)?;
                    Plan::Select(node)
                }
                other => other,
            };
        }
        Ok(plan)
    }
}
