impl ConstantFolding {
    /// Folds constant expressions in a node.
    pub fn fold(mut expr: Expression) -> Result<Expression> {
        expr.transform(&|e| Ok(e), &Self::fold)
    }

    fn fold(&self, expr: Expression) -> Result<Expression> {
        use Expression::*;

        Ok(match expr {
            And(l, r) => {
                let l = self.fold(*l)?;
                let r = self.fold(*r)?;
