                    (Boolean(false), _) => Boolean(false).into(),
                    (_, Boolean(false)) => Boolean(false).into(),
                    (Boolean(l), Boolean(r)) => Boolean(l && r).into(),
                    _ => And(l.into(), r.into()),
                }
            }
            Or(l, r) => {
                let l = self.fold(*l)?;
                let r = self.fold(*r)?;
                match (l.evaluate(None)?, r.evaluate(None)?) {
                    (Boolean(true), _) => Boolean(true).into(),
                    (_, Boolean(true)) => Boolean(true).into(),
                    (Boolean(false), Boolean(false)) => Boolean(false).into(),
                    (Boolean(l), Boolean(r)) => Boolean(l || r).into(),
                    _ => Or(l.into(), r.into()),
                }
            }
            Equal(l, r) => {
                let l = self.fold(*l)?;
                let r = self.fold(*r)?;
                match (l.evaluate(None)?, r.evaluate(None)?) {
                    (l, r) if l == r => Boolean(true).into(),
                    (l, r) => Equal(l.into(), r.into()),
                }
            }
            NotEqual(l, r) => {
                let l = self.fold(*l)?;
                let r = self.fold(*r)?;
