   104	                *count += 1;
   105	                *sum = sum.checked_add(&value)?;
   106	            }
   107	            Accumulator::Count(c) => {
   108	                *c += 1;
   109	            }
   110	            Accumulator::Max(max) => {
   111	                if value > *max.as_ref().unwrap_or(&Value::Null) {
   112	                    *max = Some(value);
   113	                }
   114	            }
   115	            Accumulator::Min(min) => {
   116	                if value < *min.as_ref().unwrap_or(&Value::Null) {
   117	                    *min = Some(value);
   118	                }
   119	            }
   120	            Accumulator::Sum(sum) => {
   121	                match sum {
   122	                    Some(s) => *sum = Some(s.checked_add(&value)?),
   123	                    None => *sum = Some(value),
   124	                }
   125	            }
   126	            Accumulator::Median(values) => {
   127	                values.push(value);
   128	            }
   129	            Accumulator::StringAgg { values, delimiter } => {
